    public static final String EMPTY = "{\"class\":[],\"filters\":{}}";

    /**
     * 取内置配置。
     *
     * @param name {@code ext.n} 的值（如 {@code 哔哩合集}）
     * @return 原始 JSON；未命中返回 null（调用方继续走 ext.json 分支）
     */
    public static String config(String name) {
        return name == null ? null : CONFIGS.get(name);
    }

    /**
     * 全部内置配置名。
     *
     * @return 名字数组（插入顺序，与上游 if 链顺序一致）
     */
    public static String[] names() {
        return CONFIGS.keySet().toArray(new String[0]);
    }
